// Executable target oracles for the mandatory matrix. They validate observations, not mocks.
// Baseline pure cases are generated by baseline.cjs. Later integration drivers supply
// actual API/SQL/browser observations as JSON to --observations <file>.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const baseline = require('./baseline.json');
const integrations = [
 ['A12','Existing/retried/concurrent link saves', {parallel_requests:20,distinct_active_rules:1,distinct_part_links:1,all_outcomes_saved_or_existing:true,no_association_side_effect:true}],
 ['A13','Chassis-only claim without invented engine', {chassis_id_retained:true,engine_id:null,model_fabricated:false,scope_preserved:true}],
 ['A14','Make-only and unknown vs unrestricted', {make_only_status:'needs_review',missing_engine_mode:'not_supplied',unrestricted_requires_approved_evidence:true,confirmed_without_details:false}],
 ['A15','Valid wrong ID and conflicting parent at every writer', {parser_rejects:true,application_route_rejects:true,part_create_rejects:true,part_edit_rejects:true,receiving_create_rejects:true,partial_writes:0}],
 ['A16','Variants, exclusions, position, market and disjoint years', {variant_rows_preserved:2,disjoint_year_rules:2,market_rules:2,position_rules:2,exclusion_overrides_include:true,unknown_exclusion_yields:'needs_details',restriction_loss:0}],
 ['A17','Incorrect legacy association, stale review, changed taxonomy', {legacy_confirmed:false,stale_http_status:409,post_edit_cache_current:true,other_process_cache_current:true,engine_query_does_not_match_different_explicit_engine:true}],
 ['A18','Scoped aliases, separate correction and dismissal', {whole_phrase_alias_http_status:422,correction_does_not_create_alias:true,ambiguous_alias_not_auto_resolved:true,dismissed_count_after_unchanged_reparse:0,resurface_requires_reason:true}],
 ['A19','Research outage, no result, untrusted fetch and evidence approval', {research_endpoint_exists:true,outage_manual_usable:true,no_result:'insufficient',no_automatic_approval:true,ssrf_blocked:true,unlicensed_passage_persisted:false,engine_association_does_not_certify_part:true}],
 ['A20','Unauthorized direct/bulk/staged writes and races', {unauthorized_http_status:403,partial_writes:0,client_verification_rejected:true,stale_rule_http_status:409,idempotency_changed_body_http_status:409}],
 ['A21','Search/display/mobile round trip and new taxonomy', {atomic_engine_ids_preserved:true,qualifiers_preserved:true,status_visible:true,text_only_offline_not_confirmed:true,new_taxonomy_visible:true,unknown_year_not_confirmed:true}],
];
function run(observations = {}) {
 const results = baseline.results.map(r=>({id:r.id,case:r.input,status:r.target_passes?'pass':'fail',difference:r.difference}));
 for(const [id,name,expected] of integrations) {
  if(!Object.hasOwn(observations,id)) {results.push({id,case:name,status:'not_verified',required_observations:expected});continue;}
  const missing=Object.keys(expected).filter(key=>!Object.hasOwn(observations[id],key));
  try {for(const [key,value]of Object.entries(expected)) if(Object.hasOwn(observations[id],key)) assert.deepEqual(observations[id][key],value,`${id}.${key}`);results.push({id,case:name,status:missing.length?'not_verified':'pass',unverified_subchecks:missing});}
  catch(e){results.push({id,case:name,status:'fail',difference:e.message,unverified_subchecks:missing});}
 }
 return {results,summary:{pass:results.filter(r=>r.status==='pass').length,fail:results.filter(r=>r.status==='fail').length,not_verified:results.filter(r=>r.status==='not_verified').length},note:'Integration observations must come from a disposable real PostgreSQL API/browser run. This runner does not fabricate or execute those operations.'};
}
if(require.main===module){const i=process.argv.indexOf('--observations');const data=i>=0?JSON.parse(fs.readFileSync(path.resolve(process.argv[i+1]),'utf8')):require('./observations-from-baseline.cjs')(require('./api-baseline.json'),baseline);const report=run(data);console.log(JSON.stringify(report,null,2));if(report.summary.fail||report.summary.not_verified)process.exitCode=1;}
module.exports={run,integrations};
